  return { id: decision.record_id, content: replacing ? decision.merged_content ?? memory.content : memory.content,
    type: replacing ? decision.merged_type ?? memory.type : memory.type,
    priority: replacing ? decision.merged_priority ?? memory.priority : memory.priority,
    scene_name: memory.scene_name, source_message_ids: memory.source_message_ids, metadata: memory.metadata,
    timestamps: [recordedAt], createdAt: recordedAt, updatedAt: recordedAt, version, ...scope };
}

